script:
// 本地夹具 JS 规则示例：演示 triomi.* 宿主函数与流程编排。
// 它解析出的数据与声明式规则 local-fixture.json 一致，方便对照两种写法。

async function parseList(html) {
  var rows = await triomi.select(html, '.list .item', {
    title: 'a.title',
    url: { selector: 'a.title', attr: 'href', absolute: true },
    coverUrl: { selector: 'img.cover', attr: 'data-src', absolute: true },
    author: '.author'
  });
  var items = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    var match = /\/manga\/(\d+)/.exec(row.url || '');
    if (!match) continue;
    items.push({
      remoteId: match[1],
      title: row.title,
      url: row.url,
      coverUrl: row.coverUrl,
      author: row.author
    });
  }
  return items;
}

async function discover(url, page) {
  var res = await triomi.fetch(url);
  return await parseList(res.body);
}

async function search(keyword, page) {
  var url = triomi.baseUrl + '/search?q=' + encodeURIComponent(keyword) + '&page=' + page;
  var res = await triomi.fetch(url);
  return await parseList(res.body);
}

async function detail(url, item) {
  var res = await triomi.fetch(url);
  var chapters = await triomi.select(res.body, '.chapters li', {
    title: 'a',
    url: { selector: 'a', attr: 'href', absolute: true }
  });
  for (var i = 0; i < chapters.length; i++) {
    var match = /\/chapter\/([\w-]+)/.exec(chapters[i].url || '');
    chapters[i].remoteId = match ? match[1] : chapters[i].url;
  }
  return {
    item: {
      title: await triomi.value(res.body, 'h1'),
      description: await triomi.value(res.body, '.summary')
    },
    chapters: chapters
  };
}

async function content(url, chapter) {
  var res = await triomi.fetch(url);
  var images = await triomi.values(res.body, '#reader img', 'data-original');
  if (images.length === 0) {
    images = await triomi.values(res.body, '#reader img', 'src');
  }
  return { images: images };
}
